// Normalize inbound emails, classify the product group and flag anything
// a human should look at. Config values come from the Routing Config node.
const items = $input.all();
const cfg = items[0].json;
const ownerRules = Object.fromEntries(
  String(cfg.ownerByProductGroup || '')
    .split(';')
    .map((r) => r.split('='))
    .filter((p) => p.length === 2)
);
const seen = new Set();
const out = [];
for (const item of items) {
  const e = item.json;
  const from = String(e.from || '');
  const emailMatch = from.match(/<([^>]+)>/);
  const fromEmail = String(emailMatch ? emailMatch[1] : from).trim().toLowerCase();
  const fromName = from.replace(/<[^>]+>/, '').replace(/"/g, '').trim() || fromEmail;
  const subject = String(e.subject || '').trim();
  const text = String(e.textPlain || '').slice(0, 2000);
  const attachments = (e.attachments || []).map((a) => a.filename || 'attachment');
  const haystack = (subject + ' ' + text).toLowerCase();
  const productGroup = /service|support|wartung|wartungsvertrag/.test(haystack)
    ? 'service'
    : /produkt|artikel|bestellung|product|order/.test(haystack)
      ? 'products'
      : 'other';
  const ownerEmail = ownerRules[productGroup] || String(cfg.salesOwnerFallback || '');
  const messageId = String(e.messageId || fromEmail + '|' + subject);
  const isDuplicate = seen.has(messageId);
  seen.add(messageId);
  const problems = [];
  if (!fromEmail || !subject || productGroup === 'other') problems.push('missing sender or subject, or no product group matched');
  if (isDuplicate) problems.push('duplicate message id within this run');
  if (!ownerEmail) problems.push('no owner mapped for this product group');
  out.push({
    json: {
      messageId,
      fromEmail,
      fromName,
      subject,
      bodyPreview: text.slice(0, 300),
      attachments,
      productGroup,
      ownerEmail,
      senderAddress: cfg.senderAddress,
      reviewInbox: cfg.reviewInbox,
      needsReview: problems.length > 0,
      reviewReason: problems.join('; '),
    },
  });
}
return out;

